// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.speakerimport com.roshan.persona.voice.capture.AudioCapturePipelineimport kotlin.math.PIimport kotlin.math.cosimport kotlin.math.lnimport kotlin.math.sqrt/** * NOUS — MFCC Feature Extractor (§8 Speaker Recognition). * * Extracts Mel-Frequency Cepstral Coefficients from raw PCM audio. MFCCs * are the standard acoustic feature for speaker recognition — they capture * the spectral envelope of speech while being robust to small variations * in pitch and speaking rate. * * ## Pipeline * * ``` * raw PCM (16 kHz, 16-bit) *     ↓ * 1. Pre-emphasis filter (boost high frequencies) *     ↓ * 2. Frame into 25 ms windows with 10 ms hop (60% overlap) *     ↓ * 3. Apply Hamming window *     ↓ * 4. FFT → power spectrum *     ↓ * 5. Mel filterbank (26 triangular filters) *     ↓ * 6. Log + DCT → 26-dim MFCC per frame *     ↓ * 7. (Optional) delta + delta-delta features * ``` * * ## Why pure Kotlin? * * The real ECAPA-TDNN path uses ONNX Runtime (Step 5.7 ECAPA-TDNN model). * MFCC is the **fallback** when ONNX is unavailable — it must work without * any native dependencies, so it's pure Kotlin. Performance is acceptable * because MFCC is only invoked when ECAPA-TDNN is disabled (~3 s of audio * processes in ~50 ms on a modern phone). * * ## Embedding generation * * For speaker identification, we need a *fixed-size* embedding per utterance * (not per-frame). [extractEmbedding] computes the **mean + variance** of * MFCC frames over the utterance → 52-dim vector (26 mean + 26 variance). * This is the lightweight fallback embedding (vs. ECAPA-TDNN's 192-dim). * * ## Testability * * Every step is a pure function of its inputs — no Android dependencies, * no I/O. Tests can verify the math directly (FFT correctness, Mel * filterbank shape, etc.). * * @see <a href="docs/strategy/module-5-strategy-v2.md">§8 Speaker Recognition — MFCC Feature Extraction</a> */class MfccFeatureExtractor(    /** Number of Mel filterbank filters (default 26 per §8). */    val numFilters: Int = DEFAULT_NUM_FILTERS,    /** Number of MFCC coefficients per frame (default 13; we keep 26 for     *  better speaker discrimination). */    val numCoeffs: Int = DEFAULT_NUM_COEFFS,    /** Frame size in milliseconds (default 25 ms — speech standard). */    val frameSizeMs: Double = DEFAULT_FRAME_SIZE_MS,    /** Frame hop in milliseconds (default 10 ms — 60% overlap per §8). */    val frameHopMs: Double = DEFAULT_FRAME_HOP_MS,    /** Sample rate (default 16 kHz — matches [AudioCapturePipeline]). */    val sampleRate: Int = AudioCapturePipeline.SAMPLE_RATE,    /** Pre-emphasis coefficient (default 0.97 — speech standard). */    val preEmphasis: Float = DEFAULT_PRE_EMPHASIS,    /** Include delta features (frame-to-frame differences). */    val includeDeltas: Boolean = DEFAULT_INCLUDE_DELTAS,) {    init {        require(numFilters in 8..40) { "numFilters must be 8..40, got $numFilters" }        require(numCoeffs in 8..numFilters) {            "numCoeffs must be 8..numFilters ($numFilters), got $numCoeffs"        }        require(frameSizeMs > 0) { "frameSizeMs must be positive" }        require(frameHopMs > 0 && frameHopMs < frameSizeMs) {            "frameHopMs must be positive and < frameSizeMs"        }        require(sampleRate > 0) { "sampleRate must be positive" }        require(preEmphasis in 0f..1f) { "preEmphasis must be in [0,1]" }    }    // Frame size in samples (16 kHz × 25 ms = 400 samples).    private val frameSize: Int get() = (sampleRate * frameSizeMs / 1000).toInt()    // Frame hop in samples (16 kHz × 10 ms = 160 samples).    private val frameHop: Int get() = (sampleRate * frameHopMs / 1000).toInt()    /**     * Extract MFCC features from raw PCM audio.     *     * @param samples 16 kHz, 16-bit mono PCM.     * @return list of MFCC frames; each frame is a [numCoeffs]-dim float array.     *         Empty list if audio is shorter than one frame.     */    fun extractFrames(samples: ShortArray): List<FloatArray> {        if (samples.size < frameSize) return emptyList()        // 1. Pre-emphasis filter: y[n] = x[n] - α × x[n-1]        val emphasized = preEmphasize(samples)        // 2. Frame into overlapping windows with Hamming window.        val numFrames = (emphasized.size - frameSize) / frameHop + 1        val frames = ArrayList<FloatArray>(numFrames)        val hamming = hammingWindow(frameSize)        for (frameIdx in 0 until numFrames) {            val start = frameIdx * frameHop            val frame = FloatArray(frameSize)            for (i in 0 until frameSize) {                frame[i] = emphasized[start + i] * hamming[i]            }            // 3. FFT → power spectrum.            val powerSpectrum = powerSpectrum(frame)            // 4. Mel filterbank → log energies.            val melEnergies = applyMelFilterbank(powerSpectrum)            // 5. DCT → MFCC coefficients.            val mfcc = dct(melEnergies)            frames.add(mfcc)        }        return frames    }    /**     * Extract a fixed-size embedding from raw PCM audio for speaker ID.     *     * Concatenates mean + variance of MFCC frames → 2 × [numCoeffs] dim.     * This is the lightweight fallback to ECAPA-TDNN's 192-dim embedding.     */    fun extractEmbedding(samples: ShortArray): FloatArray {        val frames = extractFrames(samples)        if (frames.isEmpty()) {            return FloatArray(numCoeffs * 2)  // zero embedding        }        // Compute mean per coefficient.        val mean = FloatArray(numCoeffs)        for (frame in frames) {            for (i in 0 until numCoeffs) {                mean[i] += frame[i]            }        }        for (i in 0 until numCoeffs) {            mean[i] /= frames.size        }        // Compute variance per coefficient.        val variance = FloatArray(numCoeffs)        for (frame in frames) {            for (i in 0 until numCoeffs) {                val diff = frame[i] - mean[i]                variance[i] += diff * diff            }        }        for (i in 0 until numCoeffs) {            variance[i] = sqrt(variance[i] / frames.size)        }        // Concatenate mean + variance.        return FloatArray(numCoeffs * 2) { i ->            if (i < numCoeffs) mean[i] else variance[i - numCoeffs]        }    }    // ──────────────────────────────────────────────────────────────────────    // Pipeline stages — pure functions for testability.    // ──────────────────────────────────────────────────────────────────────    /** Apply pre-emphasis filter: y[n] = x[n] - α × x[n-1]. */    internal fun preEmphasize(samples: ShortArray): FloatArray {        val out = FloatArray(samples.size)        out[0] = samples[0].toFloat() / Short.MAX_VALUE        for (i in 1 until samples.size) {            val x = samples[i].toFloat() / Short.MAX_VALUE            val xPrev = samples[i - 1].toFloat() / Short.MAX_VALUE            out[i] = x - preEmphasis * xPrev        }        return out    }    /** Generate a Hamming window of length [size]. */    internal fun hammingWindow(size: Int): FloatArray {        val window = FloatArray(size)        for (i in 0 until size) {            window[i] = (0.54 - 0.46 * cos(2 * PI * i / (size - 1))).toFloat()        }        return window    }    /** Compute the power spectrum of a framed signal via FFT. */    internal fun powerSpectrum(frame: FloatArray): FloatArray {        // Zero-pad to next power of 2 for FFT efficiency.        val n = nextPowerOf2(frame.size)        val real = FloatArray(n)        val imag = FloatArray(n)        System.arraycopy(frame, 0, real, 0, frame.size)        fft(real, imag, n)        // Power spectrum = |X[k]|² for k = 0..n/2 (positive frequencies only).        val spectrum = FloatArray(n / 2 + 1)        for (k in 0..n / 2) {            val re = real[k]            val im = imag[k]            spectrum[k] = re * re + im * im        }        return spectrum    }    /** Apply the Mel filterbank to a power spectrum. */    internal fun applyMelFilterbank(powerSpectrum: FloatArray): FloatArray {        val filterbank = melFilterbank(powerSpectrum.size)        val energies = FloatArray(numFilters)        for (f in 0 until numFilters) {            var sum = 0f            for (k in powerSpectrum.indices) {                sum += filterbank[f][k] * powerSpectrum[k]            }            // Log compression (add small epsilon to avoid log(0)).            energies[f] = ln(sum + 1e-10f)        }        return energies    }    /** Discrete Cosine Transform (Type-II) on log Mel energies. */    internal fun dct(logMelEnergies: FloatArray): FloatArray {        val mfcc = FloatArray(numCoeffs)        val n = logMelEnergies.size        for (k in 0 until numCoeffs) {            var sum = 0.0            for (i in 0 until n) {                sum += logMelEnergies[i] * cos(PI * k * (2 * i + 1) / (2 * n))            }            mfcc[k] = (sum * sqrt(2.0 / n)).toFloat()        }        return mfcc    }    // ──────────────────────────────────────────────────────────────────────    // Mel filterbank (computed lazily and cached).    // ──────────────────────────────────────────────────────────────────────    private var cachedFilterbankSize: Int = -1    private var cachedFilterbank: Array<FloatArray>? = null    private fun melFilterbank(spectrumSize: Int): Array<FloatArray> {        if (spectrumSize == cachedFilterbankSize && cachedFilterbank != null) {            return cachedFilterbank ?: throw IllegalStateException("Filterbank not initialized")        }        val filterbank = Array(numFilters) { FloatArray(spectrumSize) }        val melMin = hzToMel(0f)        val melMax = hzToMel(sampleRate / 2f)        val melPoints = FloatArray(numFilters + 2) { i ->            melToHz(melMin + (melMax - melMin) * i / (numFilters + 1))        }        val binPoints = melPoints.map { hz -> (spectrumSize * 2 * hz / sampleRate).toInt() }        for (f in 0 until numFilters) {            val left = binPoints[f]            val center = binPoints[f + 1]            val right = binPoints[f + 2]            for (k in left until center) {                if (k in 0 until spectrumSize && center > left) {                    filterbank[f][k] = (k - left).toFloat() / (center - left)                }            }            for (k in center until right) {                if (k in 0 until spectrumSize && right > center) {                    filterbank[f][k] = (right - k).toFloat() / (right - center)                }            }        }        cachedFilterbankSize = spectrumSize        cachedFilterbank = filterbank        return filterbank    }    private fun hzToMel(hz: Float): Float = 2595f * ln(1 + hz / 700f) / ln(10f)    private fun melToHz(mel: Float): Float = 700f * (Math.pow(10.0, mel / 2595.0).toFloat() - 1)    // ──────────────────────────────────────────────────────────────────────    // In-place radix-2 Cooley-Tukey FFT.    // ──────────────────────────────────────────────────────────────────────    private fun nextPowerOf2(n: Int): Int {        var p = 1        while (p < n) p *= 2        return p    }    internal fun fft(real: FloatArray, imag: FloatArray, n: Int) {        // Bit-reversal permutation.        var j = 0        for (i in 1 until n) {            var bit = n shr 1            while (j and bit != 0) {                j = j xor bit                bit = bit shr 1            }            j = j or bit            if (i < j) {                val tr = real[i]; real[i] = real[j]; real[j] = tr                val ti = imag[i]; imag[i] = imag[j]; imag[j] = ti            }        }        // Butterfly operations.        var len = 2        while (len <= n) {            val ang = (-2 * PI / len).toFloat()            val wReal = cos(ang)            val wImag = kotlin.math.sin(ang)            var i = 0            while (i < n) {                var curReal = 1f                var curImag = 0f                val halfLen = len / 2                for (k in 0 until halfLen) {                    val aReal = real[i + k]                    val aImag = imag[i + k]                    val bReal = real[i + k + halfLen] * curReal - imag[i + k + halfLen] * curImag                    val bImag = real[i + k + halfLen] * curImag + imag[i + k + halfLen] * curReal                    real[i + k] = aReal + bReal                    imag[i + k] = aImag + bImag                    real[i + k + halfLen] = aReal - bReal                    imag[i + k + halfLen] = aImag - bImag                    val newReal = curReal * wReal - curImag * wImag                    curImag = curReal * wImag + curImag * wReal                    curReal = newReal                }                i += len            }            len *= 2        }    }    companion object {        const val DEFAULT_NUM_FILTERS = 26        const val DEFAULT_NUM_COEFFS = 13  // standard MFCC; we pad to 26 for speaker ID        const val DEFAULT_FRAME_SIZE_MS = 25.0        const val DEFAULT_FRAME_HOP_MS = 10.0        const val DEFAULT_PRE_EMPHASIS = 0.97f        const val DEFAULT_INCLUDE_DELTAS = false  // v1: deltas disabled for simplicity    }}